# The ones still mostly machine-drafted (i18n/<lang>.ai.json): the footer says
# so under the picker, with a link to help check them.
UI_LANGS_DRAFTED = ("es", "fr", "pt", "ru", "ko", "tr")
TRANSLATING_URL = f"{REPO_URL}/blob/main/docs/translating.md"
# A language whose file names fewer of the English name keys than this is left
# out rather than shown half in English (the game's ar.json names none).
NAME_COVERAGE = 0.5


def _name_keys(english: dict[str, str]) -> list[str]:
    """The keys of the English text that the payload's `names` carries."""
    return sorted(k for k, v in english.items()
                  if k.startswith(NAME_PREFIXES) and not k.endswith("_description") and v)


def name_coverage(english: dict[str, str], other: dict[str, str]) -> float:
    """The share of the English name keys that another language's text names."""
    keys = _name_keys(english)
    named = sum(1 for k in keys if isinstance(other.get(k), str) and other[k].strip())
    return named / len(keys) if keys else 0.0


def name_table(english: dict[str, str], other: dict[str, str]) -> dict[str, str]:
    """One language's game names by key, for the page to lay over `names`.

    Only the keys `names` carries, and only where the language words it
    differently: a key left out reads as English, which is also what the page
    does for a key the language has no word for.
    """
    return {k: other[k] for k in _name_keys(english)
            if isinstance(other.get(k), str) and other[k].strip() and other[k] != english[k]}


def hood_key(row: dict | None) -> str | None:
    """A building-table row's neighbourhood as the game's key, or None."""
    hood = row.get("h") if row else None
    return HOOD_PREFIX + hood if hood else None


def hood_label(key: str | None, default: str = "") -> str:
    """A neighbourhood key's English name, for Python's own sentences."""
    if not key:
        return default
    return HOOD_LABEL.get(key) or _plain(key.removeprefix(HOOD_PREFIX))

# Every building in the city, from the game's fixed map: make_buildings.py
# generates ba_buildings.json beside this file, and the browser worker writes it
# to /data/. A missing table is not an error — the [XX] prefix in the business
# name is then the only neighbourhood signal, as before the table existed.
_buildings = None


def load_buildings() -> dict:
    """ba_buildings.json as {(street slug, number): row}, read once.

    Row keys are single letters to keep the file small: s street slug, n number,
    h neighbourhood, t building type, z size code, m square metres, x traffic,
    v building version (absent from a table made before versions were read).
    """
    global _buildings
    if _buildings is None:
        for path in (
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "ba_buildings.json"),
            "/data/ba_buildings.json",  # where the worker puts it in a browser
        ):
            try:
                with open(path, encoding="utf-8") as fh:
                    _buildings = {(r["s"], r["n"]): r for r in json.load(fh)}
                break
            except (OSError, ValueError):
                continue  # not here, or unreadable: try the next place
        else:
            _buildings = {}
    return _buildings


# The game's own arrival curves, from its Addressables bundles:
# make_demand_curves.py generates ba_demand_curves.json beside this file and the
# browser worker writes it to /data/, exactly as with the building table. Read it
# lazily, never at import time: in Pyodide nothing is on the virtual filesystem
# when this module is imported.
_demand_curves = None


def load_demand_curves() -> dict:
    """ba_demand_curves.json as {"types": {...}, "items": {...}}, read once.

    Per business type: `d` the seven day multipliers indexed by the board's
    weekday, `h` the twenty-four hour multipliers, `p` the type's primary
    products. Per item name: its productSalesRatio, non-zero ones only, so a
    name that is absent sells nothing. A missing file is not an error — the
    arrival ceiling is simply unavailable, and every number the board states
    comes off the measured hour grid regardless.
    """
    global _demand_curves
    if _demand_curves is None:
        for path in (
            os.path.join(
                os.path.dirname(os.path.abspath(__file__)), "ba_demand_curves.json"
            ),
            "/data/ba_demand_curves.json",  # where the worker puts it in a browser
        ):
            try:
                with open(path, encoding="utf-8") as fh:
                    loaded = json.load(fh)
                _demand_curves = {
                    "types": loaded.get("types") or {},
                    "items": loaded.get("items") or {},
                }
                break
            except (OSError, ValueError, AttributeError):
                continue  # not here, or unreadable: try the next place
        else:
            _demand_curves = {"types": {}, "items": {}}
    return _demand_curves


# The game's furniture prices and wall and floor materials, from its bundles:
# make_item_prices.py generates ba_item_prices.json beside this file and the
# browser worker writes it to /data/, as with the curves. Read lazily, never at
# import time.
_item_prices = None


def load_item_prices() -> dict:
    """ba_item_prices.json as {"items": {...}, "materials": {...}}, read once.

    Per item name: `p` Item.defaultMarketPrice, `t` its type bit flags. Per
    material uuid (the MaterialID a save's interiorDesigns slots hold): `t` 1
    floor or 2 wall, `p` InteriorMaterialPreset.price, `b` whether it can be
    bought. A missing file is not an error: an item then counts at what the
    save says was paid for it, and materials at nothing.
    """
    global _item_prices
    if _item_prices is None:
        for path in (
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "ba_item_prices.json"),
            "/data/ba_item_prices.json",  # where the worker puts it in a browser
        ):
            try:
                with open(path, encoding="utf-8") as fh:
                    loaded = json.load(fh)
                _item_prices = {
                    "items": loaded.get("items") or {},
                    "materials": loaded.get("materials") or {},
                }
                break
            except (OSError, ValueError, AttributeError):
                continue  # not here, or unreadable: try the next place
        else:
            _item_prices = {"items": {}, "materials": {}}
    return _item_prices


